const markConversationNotificationsRead = `-- name: MarkConversationNotificationsRead :exec
UPDATE notifications SET read_at = $1
WHERE user_id = $2 AND target_type = 'dm_conversation' AND target_id = $3 AND read_at IS NULL
`

type MarkConversationNotificationsReadParams struct {
	ReadAt         pgtype.Timestamptz
	UserID         pgtype.UUID
	ConversationID pgtype.UUID
}

// Konuşma okununca o konuşmanın bildirimleri de okunmuş olur.
func (q *Queries) MarkConversationNotificationsRead(ctx context.Context, arg MarkConversationNotificationsReadParams) error {
	_, err := q.db.Exec(ctx, markConversationNotificationsRead, arg.ReadAt, arg.UserID, arg.ConversationID)
	return err
}

const markConversationRead = `-- name: MarkConversationRead :exec

INSERT INTO dm_conversation_reads (conversation_id, user_id, last_read_message_id, read_at)
VALUES ($1, $2, $3, $4)
ON CONFLICT (conversation_id, user_id) DO UPDATE
SET last_read_message_id = GREATEST(dm_conversation_reads.last_read_message_id, EXCLUDED.last_read_message_id),
    read_at = CASE WHEN EXCLUDED.last_read_message_id > dm_conversation_reads.last_read_message_id
                   THEN EXCLUDED.read_at ELSE dm_conversation_reads.read_at END
`

type MarkConversationReadParams struct {
	ConversationID pgtype.UUID
	UserID         pgtype.UUID
	MessageID      pgtype.UUID
	ReadAt         pgtype.Timestamptz
}

// Okunma bilgisi.
// Okundu işareti yalnızca ileri gider (UUIDv7 zaman sıralı).
func (q *Queries) MarkConversationRead(ctx context.Context, arg MarkConversationReadParams) error {
	_, err := q.db.Exec(ctx, markConversationRead,
		arg.ConversationID,
		arg.UserID,
		arg.MessageID,
		arg.ReadAt,
	)
	return err
}

const purgeDeletedDirectMessages = `-- name: PurgeDeletedDirectMessages :execrows

DELETE FROM dm_messages
WHERE id IN (
  SELECT o.id FROM dm_messages o
  WHERE o.deleted_at < $1::timestamptz
  ORDER BY o.deleted_at
  LIMIT $2
)
`

type PurgeDeletedDirectMessagesParams struct {
	Before pgtype.Timestamptz
	N      int32
}

// Saklama ve silme.
// 30 gün: silinmiş mesajlardan bir parti kalıcı silinir.
func (q *Queries) PurgeDeletedDirectMessages(ctx context.Context, arg PurgeDeletedDirectMessagesParams) (int64, error) {
	result, err := q.db.Exec(ctx, purgeDeletedDirectMessages, arg.Before, arg.N)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

